import sys

def solve(n):
    result = []
    def recursive_sum(i, j, k, n, x, y):
        if i == x and j == y:
            return k == n - x - y
        elif i < x or j < y:
            while True:
                next_i = i + 1
                next_j = j
                next_k = k - (i + 1)
                next_x = x - 1
                next_y = y
                if next_i % 3 != 0 and next_i <= next_x and recursive_sum(next_i, next_j, next_k, n, next_x, next_y):
                    return True
                next_i = i
                next_j = j + 1
                next_k = k - (j + 1)
                next_x = x
                next_y = y - 1
                if next_j % 3 != 0 and next_j <= next_y and recursive_sum(next_i, next_j, next_k, n, next_x, next_y):
                    return True
                break
    for i in range(1, n // 2 + 1):
        if n - i > 2 and i % 3 != 0:
            x = i
            while True:
                y = x + 1
                z = n - x - y
                if y <= z and recursive_sum(i, y, z, n, x, y):
                    return "YES\n{} {} {}".format(x, y, z)
    return "NO"
