import itertools

def solve():
    x, k = map(int, input().split())

    def digit_sum(n):
        return sum(map(int, str(n)))

    def is_k_beautiful(n, k):
        return digit_sum(n) % k == 0

    candidates = (x + i for i in itertools.count())
    return next(filter(lambda n: is_k_beautiful(n, k), candidates))
