    possible_weights = list(range(1, poly_strenght + 1))

    for weight in possible_weights:
        max_lifts = 0
        has_tied = False
        lifts_poly = poly_endurance if weight <= poly_strenght else 0

        for athlete in athletes[1:]:
            strenght, endurance = athlete
            if strenght >= weight and weight <= poly_strenght:
                other_lifts = endurance
                if other_lifts > max_lifts:
                    max_lifts = other_lifts
                if other_lifts == lifts_poly:
                    has_tied = True

        if not has_tied and lifts_poly > 0 and lifts_poly >= max_lifts:
            return weight

    return -1

