import sys
input = lambda: sys.stdin.readline().rstrip()

def solve():
    n, k = map(int, input().split())
    a = list(map(int, input().split()))

    def f(l, r):
        return sum(abs(a[i] - a[i + 1]) for i in range(l, r))

    memo = {}
    def dp(i, j):
        if (i, j) not in memo:
            if i == n and j == k:
                result = 0
            elif i == n or j > k:
                result = float('inf')
            else:
                result = min(dp(min(n - 1, r), j + 1) if r >= i else float('inf') 
                             for r in range(i, n)) + f(i, min(n - 1, max(i, n - k + j))))

            memo[(i, j)] = result
        return memo[(i, j)]

    result = dp(0, 0)
    del memo[(n, k)]

    while len(memo) > 0:
        for key in list(memo):
            if type(memo[key]) == float and memo[key] != float('inf'):
                continue
            elif float('inf') in [dp(key[0], min(k - 1, max(0, key[1] - 1))), dp(max(i + 1 for i in range(n) if f(min(n - k + j, n), n)), min(j + 1, k))]:
                memo.pop(key)

    return result

