import math

def solve():
    n = int(input())
    a = list(map(int, input().split()))
    return min(operations(i, sum(a) % 2) for i in range(n))

def operations(k, mod):
    count = 0
    temp = k
    if not (mod or parity(temp)):
        return count

    while parity(temp) == mod:
        count += 1
        temp //= 2

    return count

def parity(x): 
    return x % 2
