However, we can simplify and speed up this calculation using the formula for the sum of an arithmetic series. Here's how:

```python
import math

def solve(n, m):
    if n == 1:
        return (m * (m + 1)) // 2
    elif m == 1:
        return (n * (n + 1)) // 2

    total_sum = (n * (n - 1) * m) // 2 + (m * (m + 1)) // 2

    # sum of (m*(m-1)/2)*n 
    partial_sum_rows = n
    for i in range(2, n):
        total_sum -= partial_sum_rows
        partial_sum_rows += m - i

    return total_sum
```

```python
import sys

def solve():
    n = int(sys.stdin.readline().split()[0])
    m = int(sys.stdin.readline().split()[1])

    def factorial(x):
        if x == 1:
            return 1
        else:
            return x + factorial(x-1)

    result = (factorial(n) * factorial(m)) // (factorial(n+m))
    result += ((n*m*(n+m+1))//2) - (m*(m+1)//2)
    return result

```

